class LogoTheme {
  final List<Color> waveColors;
  final List<double> waveStops;
  final String budLeft, budRight, wordA, wordB;

  const LogoTheme({
    required this.waveColors,
    required this.waveStops,
    required this.budLeft,
    required this.budRight,
    required this.wordA,
    required this.wordB,
  });
}

